-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.site_day_start(d date)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select (d + interval '4 hours') at time zone 'America/Santiago';
$function$;

grant execute on function public.site_day_start(d date) to service_role;
